// Characterization tests: pin the current client-visible behavior of the HTTP API,
// including quirks (e.g. 200 for unknown orders), so restructuring can't change them silently.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 60, BAD: undefined }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, json, string id, items echoed, total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order, { id: order.id, items: [{ sku: 'A', qty: 2 }], total: 20 })
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total is floored to whole euros', async () => {
  const order = await (await post({ items: [{ sku: 'B', qty: 1 }] })).json()
  assert.equal(order.total, 25)
})

test('total sums multiple items', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }] })).json()
  assert.equal(order.total, 61)
})

test('no discount at exactly 100', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 10 }] })).json()
  assert.equal(order.total, 100)
})

test('10% discount when raw total is above 100 (then floored)', async () => {
  assert.equal((await (await post({ items: [{ sku: 'C', qty: 2 }] })).json()).total, 108)
  assert.equal((await (await post({ items: [{ sku: 'A', qty: 11 }] })).json()).total, 99)
  assert.equal((await (await post({ items: [{ sku: 'B', qty: 5 }] })).json()).total, 114)
})

test('invalid bodies return 400 {error:"items required"}', async () => {
  const cases = [{ body: {} }, { body: { items: [] } }, { body: { items: 'x' } }, { raw: 'not json' }, { raw: '' }, { raw: 'null' }]
  for (const c of cases) {
    const res = await post(c.body, c.raw)
    assert.equal(res.status, 400, JSON.stringify(c))
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'C', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with {error:"not found"} (current quirk)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 {error:"no route"}', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/orders'], ['GET', '/orders/1/x'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['POST', '/orders/1']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored for routing', async () => {
  const res = await fetch(`${base}/orders?x=1`, { method: 'POST', body: JSON.stringify({ items: [{ sku: 'A', qty: 1 }] }) })
  assert.equal(res.status, 201)
})
EOF
